window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-569a3500e0b3fa82"]={"versions": [{"id": "FIG-569a3500e0b3fa82", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Software-Komponenten-Templates im AUTOSAR-Metamodell. Es modelliert die Deklaration expliziter Datenempfangspunkte (DataReceivePoint) innerhalb ausführbarer Einheiten (RunnableEntity) auf Basis von Datenprototypen (DataElementPrototype) für die Sender-Receiver-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>DataPrototype</code>: Abstrakte Basisklasse.</li>\n<li><code>DataElementPrototype</code> («atpPrototype»): Spezialisiert <code>DataPrototype</code>; besitzt das Attribut <code>+ isQueued: Boolean</code>.</li>\n<li><code>DataReceivePoint</code> (Identifiable): Repräsentiert die explizite Empfangsstelle für Daten. Besitzt eine Instanzreferenz <code>+dataElement 1</code> («instanceRef») auf <code>DataElementPrototype</code>.</li>\n<li><code>ExecutableEntity</code>: Abstrakte Basisklasse.</li>\n<li><code>RunnableEntity</code>: Spezialisiert <code>ExecutableEntity</code>; besitzt die Attribute <code>+ canBeInvokedConcurrently: Boolean</code>, <code>+ minimumStartInterval: Float</code> und <code>+ symbol: String</code>. Beinhaltet über eine Komposition die Empfangspunkte (<code>+dataReceivePoint *</code> zu <code>+runnable</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Metamodellstruktur dar. Zur Laufzeit bzw. Generierungszeit definiert ein <code>DataReceivePoint</code> einer <code>RunnableEntity</code> das explizite Auslesen eines über einen Sender-Receiver-Port bereitgestellten <code>DataElementPrototype</code>. Die Eigenschaft <code>isQueued</code> am Prototyp bestimmt dabei, ob der Datenempfang gepuffert (Queue) oder ungepuffert (Data-Semantik) erfolgt, während <code>canBeInvokedConcurrently</code> und <code>minimumStartInterval</code> das Ausführungsverhalten der Runnable steuern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ vorgeschrieben ist die Instanzreferenz-Beziehung von <code>DataReceivePoint</code> zu genau einem <code>DataElementPrototype</code> (<code>1</code>), während eine <code>RunnableEntity</code> beliebig viele (<code>*</code>) Empfangspunkte aggregieren kann. Der Bezeichner <code>symbol</code> fungiert als Name des C-Funktionssymbols der Runnable. Die Festlegung von <code>isQueued</code> hat determinierende Auswirkung auf die vom RTE-Generator bereitzustellenden Lese-APIs (z. B. <code>Rte_Read</code> bzw. <code>Rte_Receive</code>).</p>"}, {"id": "FIG-75b95c1243181960", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Software-Komponenten-Templates im AUTOSAR-Metamodell. Es modelliert die Deklaration expliziter Datenempfangspunkte (DataReceivePoint) innerhalb ausführbarer Einheiten (RunnableEntity) auf Basis von Datenprototypen (DataElementPrototype) für die Sender-Receiver-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>DataPrototype</code>: Abstrakte Basisklasse.</li>\n<li><code>DataElementPrototype</code> («atpPrototype»): Spezialisiert <code>DataPrototype</code>; besitzt das Attribut <code>+ isQueued :Boolean</code>.</li>\n<li><code>DataReceivePoint</code> (Identifiable): Repräsentiert die explizite Empfangsstelle für Daten. Besitzt eine Instanzreferenz <code>+dataElement 1</code> («instanceRef») auf <code>DataElementPrototype</code>.</li>\n<li><code>ExecutableEntity</code>: Abstrakte Basisklasse.</li>\n<li><code>RunnableEntity</code>: Spezialisiert <code>ExecutableEntity</code>; besitzt die Attribute <code>+ canBeInvokedConcurrently :Boolean</code>, <code>+ minimumStartInterval :Float</code> und <code>+ symbol :CIdentifier</code>. Beinhaltet über eine Komposition die Empfangspunkte (<code>+dataReceivePoint *</code> zu <code>+runnable</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Metamodellstruktur dar. Zur Laufzeit bzw. Generierungszeit definiert ein <code>DataReceivePoint</code> einer <code>RunnableEntity</code> das explizite Auslesen eines über einen Sender-Receiver-Port bereitgestellten <code>DataElementPrototype</code>. Die Eigenschaft <code>isQueued</code> am Prototyp bestimmt dabei, ob der Datenempfang gepuffert (Queue) oder ungepuffert (Data-Semantik) erfolgt, während <code>canBeInvokedConcurrently</code> und <code>minimumStartInterval</code> das Ausführungsverhalten der Runnable steuern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ vorgeschrieben ist die Instanzreferenz-Beziehung von <code>DataReceivePoint</code> zu genau einem <code>DataElementPrototype</code> (<code>1</code>), während eine <code>RunnableEntity</code> beliebig viele (<code>*</code>) Empfangspunkte aggregieren kann. Das Attribut <code>symbol</code> ist explizit als <code>CIdentifier</code> typisiert, wodurch die Einhaltung standardkonformer C-Bezeichner für die RTE-Schnittstelle erzwungen wird. <code>isQueued</code> determiniert die Signatur und Semantik der durch den RTE-Generator bereitgestellten Zugriffsfunktionen.</p>"}, {"id": "FIG-ebdb4ec26dc32b93", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Software-Komponenten-Templates in AUTOSAR Classic (R4.0). Das Diagramm verortet den expliziten Empfang von Daten im Gesamtkontext von Software-Komponententyp, internem Verhalten, Ports und Runnable-Entitäten unter Einbeziehung des AUTOSAR-Variabilitätskonzepts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SwComponentType</code> (ARElement, AtpBlueprint, AtpBlueprintable, AtpType): Abstrakte Basis für Komponenten.</li>\n<li><code>AtomicSwComponentType</code>: Spezialisiert <code>SwComponentType</code>; aggregiert über <code>+internalBehavior 0..1</code> («atpVariation,atpSplitable») das <code>SwcInternalBehavior</code>.</li>\n<li><code>PortPrototype</code> (AtpBlueprintable, AtpPrototype): Von <code>SwComponentType</code> aggregiert über <code>+port 0..*</code> («atpVariation,atpSplitable»).</li>\n<li><code>RPortPrototype</code>: Spezialisiert <code>PortPrototype</code>.</li>\n<li><code>InternalBehavior</code>: Abstrakte Basisklasse.</li>\n<li><code>SwcInternalBehavior</code>: Spezialisiert <code>InternalBehavior</code>; aggregiert über <code>+runnable 1..*</code> («atpVariation,atpSplitable») mindestens eine <code>RunnableEntity</code>.</li>\n<li><code>ExecutableEntity</code>, <code>AtpStructureElement</code>: Abstrakte Basisklassen für <code>RunnableEntity</code>.</li>\n<li><code>RunnableEntity</code>: Aggregiert <code>VariableAccess</code> über zwei getrennte Kompositionen mit Multiplizität <code>0..*</code> («atpVariation»): <code>+dataReceivePointByArgument</code> und <code>+dataReceivePointByValue</code>.</li>\n<li><code>VariableAccess</code> (Identifiable): Repräsentiert den Variablenzugriff; aggregiert per Komposition <code>+accessedVariable 1</code> eine <code>AutosarVariableRef</code>.</li>\n<li><code>AutosarVariableRef</code>: Beinhaltet die Instanzreferenz <code>+autosarVariable 0..1</code> («instanceRef») auf ein <code>DataPrototype</code> (AtpPrototype).</li>\n<li>Notiz an <code>RPortPrototype</code> / <code>DataPrototype</code>: Erfordert, dass ein entsprechender Port durch ein <code>SenderReceiverInterface</code> typisiert ist und das <code>DataPrototype</code> ein <code>VariableDataPrototype</code> sein muss.</li>\n<li>Notiz zu <code>«atpVariation»</code>: Definiert <code>Tags: Vh.latestBindingTime = PreCompileTime</code> für die variablen Relationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Strukturmodell mit Schnittstellen zur Codegenerierung: Beim expliziten Empfang von Daten unterscheidet die <code>RunnableEntity</code> strukturell zwischen der Übergabe per Argument (<code>dataReceivePointByArgument</code>) und der Rückgabe als Wert (<code>dataReceivePointByValue</code>). Beide Pfade referenzieren über <code>VariableAccess</code> und <code>AutosarVariableRef</code> die Zielvariable im Komponentenkontext. Die Auswertung der Variabilitäten erfolgt spätestens zur Vorkompilierzeit (PreCompileTime).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindlich vorgegeben ist die Trennung des expliziten Datenempfangs in By-Value- und By-Argument-Semantik (je Kardinalität <code>0..*</code>), was unmittelbar die RTE-API-Signatur der Leseoperationen festlegt. Ports müssen Sender-Receiver-Schnittstellen zugeordnet sein und auf <code>VariableDataPrototype</code> verweisen. Sämtliche gekennzeichneten Aggregationen und Referenzen unterliegen dem Stereotyp <code>«atpVariation»</code> mit der normativen Bindungszeitbeschränkung <code>PreCompileTime</code>.</p>"}, {"id": "FIG-223ea579d03d4c63", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Software-Komponenten-Templates in AUTOSAR Classic (R4.0). Das Diagramm verortet den expliziten Empfang von Daten im Gesamtkontext von Software-Komponententyp, internem Verhalten, Ports und Runnable-Entitäten unter Einbeziehung des AUTOSAR-Variabilitätskonzepts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SwComponentType</code> (ARElement, AtpBlueprint, AtpBlueprintable, AtpType): Abstrakte Basis für Komponenten.</li>\n<li><code>AtomicSwComponentType</code>: Spezialisiert <code>SwComponentType</code>; aggregiert über <code>+internalBehavior 0..1</code> («atpVariation,atpSplitable») das <code>SwcInternalBehavior</code>.</li>\n<li><code>PortPrototype</code> (AtpBlueprintable, AtpPrototype): Von <code>SwComponentType</code> aggregiert über <code>+port 0..*</code> («atpVariation,atpSplitable»).</li>\n<li><code>AbstractRequiredPortPrototype</code>: Spezialisiert <code>PortPrototype</code>.</li>\n<li><code>InternalBehavior</code>: Abstrakte Basisklasse.</li>\n<li><code>SwcInternalBehavior</code>: Spezialisiert <code>InternalBehavior</code>; aggregiert über <code>+runnable 1..*</code> («atpVariation,atpSplitable») mindestens eine <code>RunnableEntity</code>.</li>\n<li><code>ExecutableEntity</code>, <code>AtpStructureElement</code>: Abstrakte Basisklassen für <code>RunnableEntity</code>.</li>\n<li><code>RunnableEntity</code>: Aggregiert <code>VariableAccess</code> über zwei getrennte Kompositionen mit Multiplizität <code>0..*</code> («atpVariation»): <code>+dataReceivePointByArgument</code> und <code>+dataReceivePointByValue</code>.</li>\n<li><code>VariableAccess</code> (AtpStructureElement, Identifiable): Repräsentiert den Variablenzugriff; aggregiert per Komposition <code>+accessedVariable 1</code> eine <code>AutosarVariableRef</code>.</li>\n<li><code>AutosarVariableRef</code>: Beinhaltet die Instanzreferenz <code>+autosarVariable 0..1 «atpVariation,atpSplitable»</code> («instanceRef») auf ein <code>DataPrototype</code> (AtpPrototype).</li>\n<li>Notiz an <code>AbstractRequiredPortPrototype</code> / <code>DataPrototype</code>: Erfordert, dass <code>AbstractRequiredPortPrototype</code> durch ein <code>SenderReceiverInterface</code> typisiert ist und das <code>DataPrototype</code> ein <code>VariableDataPrototype</code> sein muss.</li>\n<li>Notiz zu <code>«atpVariation»</code>: Definiert <code>Tags: vh.latestBindingTime = preCompileTime</code> für die variablen Relationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Strukturmodell mit Schnittstellen zur Codegenerierung: Beim expliziten Empfang von Daten unterscheidet die <code>RunnableEntity</code> strukturell zwischen der Übergabe per Argument (<code>dataReceivePointByArgument</code>) und der Rückgabe als Wert (<code>dataReceivePointByValue</code>). Beide Pfade referenzieren über <code>VariableAccess</code> und <code>AutosarVariableRef</code> die Zielvariable im Komponentenkontext. Die Auswertung der Variabilitäten erfolgt spätestens zur Vorkompilierzeit (PreCompileTime).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindlich vorgegeben ist die Generalisierung auf <code>AbstractRequiredPortPrototype</code>, wodurch auch abgeleitete Required-Port-Klassen für den Sender-Receiver-Empfang zulässig sind, sofern sie mit einem <code>SenderReceiverInterface</code> typisiert sind. <code>VariableAccess</code> ist als <code>AtpStructureElement</code> klassifiziert. Die Instanzreferenz <code>autosarVariable</code> sowie die weiteren markierten Assoziationen sind als splitbar und variabel mit Bindungszeit <code>preCompileTime</code> spezifiziert.</p>"}, {"id": "FIG-deb4a676ac1c4ffb", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Software-Komponenten-Templates in AUTOSAR Classic (R4.0). Das Diagramm verortet den expliziten Empfang von Daten im Gesamtkontext von Software-Komponententyp, internem Verhalten, Ports und Runnable-Entitäten unter Einbeziehung des AUTOSAR-Variabilitätskonzepts.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SwComponentType</code> (ARElement, AtpBlueprint, AtpBlueprintable, AtpType): Abstrakte Basis für Komponenten.</li>\n<li><code>AtomicSwComponentType</code>: Spezialisiert <code>SwComponentType</code>; aggregiert über <code>+internalBehavior 0..1</code> («atpVariation,atpSplitable») das <code>SwcInternalBehavior</code>.</li>\n<li><code>PortPrototype</code> (AtpBlueprintable, AtpPrototype): Von <code>SwComponentType</code> aggregiert über <code>+port 0..*</code> («atpVariation,atpSplitable»).</li>\n<li><code>AbstractRequiredPortPrototype</code>: Spezialisiert <code>PortPrototype</code>.</li>\n<li><code>InternalBehavior</code>: Abstrakte Basisklasse.</li>\n<li><code>SwcInternalBehavior</code>: Spezialisiert <code>InternalBehavior</code>; aggregiert über <code>+runnable 1..*</code> («atpVariation,atpSplitable») mindestens eine <code>RunnableEntity</code>.</li>\n<li><code>ExecutableEntity</code>, <code>AtpStructureElement</code>: Abstrakte Basisklassen für <code>RunnableEntity</code>.</li>\n<li><code>RunnableEntity</code>: Aggregiert <code>VariableAccess</code> über zwei getrennte Kompositionen mit Multiplizität <code>0..*</code> («atpVariation»): <code>+dataReceivePointByArgument</code> und <code>+dataReceivePointByValue</code>.</li>\n<li><code>VariableAccess</code> (AtpStructureElement, Identifiable): Repräsentiert den Variablenzugriff; aggregiert per Komposition <code>+accessedVariable 1</code> eine <code>AutosarVariableRef</code>.</li>\n<li><code>AutosarVariableRef</code>: Beinhaltet die Instanzreferenz <code>+autosarVariable 0..1 «atpVariation,atpSplitable»</code> («instanceRef») auf ein <code>DataPrototype</code> (AtpPrototype).</li>\n<li>Notiz an <code>AbstractRequiredPortPrototype</code> / <code>DataPrototype</code>: Erfordert, dass <code>AbstractRequiredPortPrototype</code> durch ein <code>SenderReceiverInterface</code> typisiert ist und das <code>DataPrototype</code> ein <code>VariableDataPrototype</code> sein muss.</li>\n<li>Notiz zu <code>«atpVariation»</code>: Definiert <code>Tags: vh.latestBindingTime = preCompileTime</code> für die variablen Relationen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Strukturmodell mit Schnittstellen zur Codegenerierung: Beim expliziten Empfang von Daten unterscheidet die <code>RunnableEntity</code> strukturell zwischen der Übergabe per Argument (<code>dataReceivePointByArgument</code>) und der Rückgabe als Wert (<code>dataReceivePointByValue</code>). Beide Pfade referenzieren über <code>VariableAccess</code> und <code>AutosarVariableRef</code> die Zielvariable im Komponentenkontext. Die Auswertung der Variabilitäten erfolgt spätestens zur Vorkompilierzeit (PreCompileTime).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindlich vorgegeben ist die Generalisierung auf <code>AbstractRequiredPortPrototype</code>, wodurch auch abgeleitete Required-Port-Klassen für den Sender-Receiver-Empfang zulässig sind, sofern sie mit einem <code>SenderReceiverInterface</code> typisiert sind. <code>VariableAccess</code> ist als <code>AtpStructureElement</code> klassifiziert. Die Instanzreferenz <code>autosarVariable</code> sowie die weiteren markierten Assoziationen sind als splitbar und variabel mit Bindungszeit <code>preCompileTime</code> spezifiziert.</p>"}], "trans": [{"from": "FIG-569a3500e0b3fa82", "to": "FIG-75b95c1243181960", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Attribut <code>symbol</code> in <code>RunnableEntity</code>: Datentyp von <code>String</code> zu <code>CIdentifier</code> präzisiert.</li>\n</ul>"}, {"from": "FIG-75b95c1243181960", "to": "FIG-ebdb4ec26dc32b93", "fr": "R3.2.3", "tr": "R4.0.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Metamodell-Refactoring: <code>DataReceivePoint</code> entfällt und wird durch <code>VariableAccess</code> und <code>AutosarVariableRef</code> ersetzt.</li>\n<li><code>RunnableEntity</code>: Die Komposition <code>+dataReceivePoint <em></code> entfällt; stattdessen besitzt <code>RunnableEntity</code> die zwei Kompositionsrollen <code>+dataReceivePointByArgument 0..</em></code> und <code>+dataReceivePointByValue 0..*</code> auf <code>VariableAccess</code>.</li>\n<li><code>AutosarVariableRef</code>: Referenziert über <code>«instanceRef»</code> die Zielgröße <code>+autosarVariable 0..1</code> (<code>DataPrototype</code>) und ist per Komposition <code>+accessedVariable 1</code> an <code>VariableAccess</code> gebunden.</li>\n<li>Einbettung in den Komponentenkontext: <code>AtomicSwComponentType</code> spezialisiert <code>SwComponentType</code> und aggregiert <code>SwcInternalBehavior</code> (<code>+internalBehavior 0..1</code>), welches wiederum <code>RunnableEntity</code> aggregiert (<code>+runnable 1..*</code>).</li>\n<li><code>SwComponentType</code> aggregiert <code>+port 0..*</code> (<code>PortPrototype</code>), wovon <code>RPortPrototype</code> abgeleitet ist.</li>\n<li>Variabilitäts-Stereotypen (<code>«atpVariation»</code>, <code>«atpSplitable»</code>) und Binding-Time-Annotationen (<code>Vh.latestBindingTime = PreCompileTime</code>) eingeführt.</li>\n<li>Zusätzliche Modellierungsrichtlinie für Ports und Prototypen als Notiz ergänzt.</li>\n</ul>"}, {"from": "FIG-ebdb4ec26dc32b93", "to": "FIG-223ea579d03d4c63", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>RPortPrototype</code> durch abstrakte Basisklasse <code>AbstractRequiredPortPrototype</code> ersetzt.</li>\n<li><code>VariableAccess</code>: Erbt nun zusätzlich von <code>AtpStructureElement</code>.</li>\n<li>Notiztext angepasst: Bezug von <code>PPortPrototype</code> auf <code>AbstractRequiredPortPrototype</code> geändert.</li>\n<li>Binding-Time-Schreibweise in Notiz von <code>Vh.latestBindingTime = PreCompileTime</code> auf <code>vh.latestBindingTime = preCompileTime</code> vereinheitlicht.</li>\n</ul>"}, {"from": "FIG-223ea579d03d4c63", "to": "FIG-deb4a676ac1c4ffb", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
